#include "EnvironmentSpecComponent.h"

UEnvironmentSpecComponent::UEnvironmentSpecComponent(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	GroundTextureTypes = { TEXT("regolith"), TEXT("basalt"), TEXT("ice") };
	Elements = { TEXT("silicon"), TEXT("iron"), TEXT("water_ice") };
}

FVector UEnvironmentSpecComponent::GetWindVelocity(float TimeSeconds) const
{
	if (!bWindSystemEnabled)
	{
		return FVector::ZeroVector;
	}
	// spec wind_variance oscillation: +/-30% on a 10s cycle
	const float Gust = 1.0f + 0.3f * FMath::Sin(TimeSeconds * (2.0f * PI / 10.0f));
	return WindBaseDirection.GetSafeNormal() * WindBaseSpeed * Gust;
}

float UEnvironmentSpecComponent::GetGravityZ() const
{
	return -980.0f * GravityG;   // UU/s^2 from spec g-multiple
}

bool UEnvironmentSpecComponent::IsInsideWorldBounds(const FVector& Location) const
{
	return Location.X >= MinLocation.X && Location.X <= MaxLocation.X
		&& Location.Y >= MinLocation.Y && Location.Y <= MaxLocation.Y
		&& Location.Z >= MinLocation.Z && Location.Z <= MaxLocation.Z;
}

bool UEnvironmentSpecComponent::ValidateSpec() const
{
	const bool bSurface = GroundTextureTypes.Num() > 0 && VegetationDensity >= 0.0f && Elements.Num() > 0;
	const bool bSky = !SkyboxType.IsEmpty() && !ColorPalette.IsEmpty();
	const bool bDust = bAccumulationEnabled || true;   // flag consumed; either state is valid
	const bool bCamera = !CameraPerspective.IsEmpty();
	return bSurface && bSky && bDust && bCamera && MaxLocation.X > MinLocation.X;
}
